window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-684ac4cd5d6a2edb"]={"versions": [{"id": "FIG-684ac4cd5d6a2edb", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm (kombiniert mit statischer Komponenten-/Lifeline-Struktur).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Autorisierungs- und Zugriffssteuerungsablaufs (Access Control Workflow) beim Zugriff einer Adaptive Application (AA) auf persistente kryptografische Schlüssel. Es definiert die Rollenteilung zwischen Identity and Access Management (IAM) als <em>Policy Decision Point</em> (PDP) und dem Key Storage Provider (KSP) als <em>Policy Enforcement Point</em> (PEP) innerhalb des Cryptography-Subsystems (<code>ara::crypto</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application (with linked Crypto Lib):</strong> \n<ul class=\"fig-list\"><li>Ausführender Prozess im User-Space, der gegen die C++-Schnittstellen von <code>ara::crypto</code> linkt. \n</li><li>Trägt applikationsspezifische IAM-Capabilities (im Execution/Application Manifest deklariert).\n</li></ul>\n</li><li><strong>Functional unit of Key Storage Provider:</strong> \n<ul class=\"fig-list\"><li>Funktionale Kernkomponente des Key Storage Providers (KSP, üblicherweise innerhalb des Crypto-Daemons oder eines geschützten Systemdienstes). \n</li><li>Verwaltet logische und physische Key-Slots und setzt Zugriffsentscheidungen durch (PEP).\n</li></ul>\n</li><li><strong>IAM unit of Key Storage Provider:</strong> \n<ul class=\"fig-list\"><li>IAM-Bewertungseinheit (PDP, Bindung an <code>ara::iam</code>), die Zugriffspolicies (Key Access Rulesets aus dem Deployment-Manifest) verwaltet und evaluiert.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kanäle:</strong>\n<ul class=\"fig-list\"><li>Kommunikationskanal AA ↔ KSP: IPC-Grenze zur Übermittlung von Slot-Anfragen und Handle-Rückgaben.\n</li><li>Interner Schnittstellenpfad KSP ↔ IAM: Synchroner Kontrollfluss zur Autorisierungsprüfung basierend auf Prozessattributen und Slot-Identifikatoren.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Access Request (AA → KSP):</strong> \n<ul class=\"fig-list\"><li>Die Applikation fordert Zugriff auf einen definierten Key Slot an (Aufruf von <code>KeyStorageProvider::OpenKeySlot()</code> o. ä.).\n</li></ul>\n</li><li><strong>Policy Evaluation Query (KSP → IAM):</strong> \n<ul class=\"fig-list\"><li>Die funktionale KSP-Einheit ermittelt die verifizierte Prozessidentität der AA (z. B. UID/PID bzw. Security Token via OS-IPC) und übermittelt <code>Key Slot ID</code> + Identitätsmerkmale an die IAM-Einheit.\n</li></ul>\n</li><li><strong>Access Control Decision (IAM → KSP):</strong> \n<ul class=\"fig-list\"><li>Die IAM-Einheit gleicht die Identität und Capabilities der AA gegen die hinterlegten Zugriffsregeln (<em>Policies / Ruleset</em>) für den angeforderten Key Slot ab (z. B. Read, Write, Erase).\n</li><li>Rückgabe des Autorisierungsentscheids (<code>Grant</code> / <code>Deny</code>) an den KSP.\n</li></ul>\n</li><li><strong>Handle Provisioning (KSP → AA):</strong> \n<ul class=\"fig-list\"><li><strong>Access granted:</strong> KSP instanziiert bzw. kapselt die Ressource und liefert ein valides Container-Handle (<code>KeySlot::Uptr</code>) an die AA zurück.\n</li><li><strong>Access denied:</strong> KSP verwirft die Anfrage und gibt ein Null-Handle bzw. einen entsprechenden Fehlercode zurück.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Fehlerbehandlung im Applikationscode:</strong> Aufrufe zur Slot-Öffnung liefern <code>ara::core::Result&lt;KeySlot::Uptr&gt;</code>. Applikationsentwickler müssen Zugriffsverweigerungen explizit über <code>ara::crypto::SecurityErrc::kAccessViolation</code> bzw. <code>kPermissionDenied</code> abfangen; ein ungeprüftes Dereferenzieren führt zum Absturz (<code>nullptr</code>).\n</li><li><strong>Manifest-Konfiguration:</strong> Zugriffsrechte sind statisch über AUTOSAR-Modellierungsmanifeste festzulegen:\n<ul class=\"fig-list\"><li><em>Crypto Service Certificate/Key Slot Deployment</em>: Definition der Ziel-Slots und deren Zugriffsmodi.\n</li><li><em>IAM Access Rule Profile / Execution Manifest</em>: Explizite Zuweisung der IAM-Capabilities an die Executable der AA. Fehlt die Manifest-Zuordnung, blockiert IAM den Zugriff per Default (<em>Deny by Default</em>).\n</li></ul>\n</li><li><strong>Stack- &amp; Plattform-Implementierung:</strong> Die Integrität der AA-Identität darf nicht auf Parametern der Applikationsebene basieren. Die funktionale KSP-Einheit muss die Identitätsinformationen zwingend über vertrauenswürdige OS-/IPC-Mechanismen (z. B. Peer-Credentials über UNIX Domain Sockets) auflösen, um Privilegienerweiterungen zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-db4a5826b5bee4f8", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Sequenzdiagramm (kombiniert mit statischer Komponenten-/Lifeline-Struktur).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Autorisierungs- und Zugriffssteuerungsablaufs (Access Control Workflow) beim Zugriff einer Adaptive Application (AA) auf persistente kryptografische Schlüssel. Es definiert die Rollenteilung zwischen Identity and Access Management (IAM) als <em>Policy Decision Point</em> (PDP) und dem Key Storage Provider (KSP) als <em>Policy Enforcement Point</em> (PEP) innerhalb des Cryptography-Subsystems (<code>ara::crypto</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Adaptive Application (with linked Crypto Lib):</strong> \n<ul class=\"fig-list\"><li>Ausführender Prozess im User-Space, der gegen die C++-Schnittstellen von <code>ara::crypto</code> linkt. \n</li><li>Trägt applikationsspezifische IAM-Capabilities (im Execution/Application Manifest deklariert).\n</li></ul>\n</li><li><strong>Functional unit of Key Storage Provider:</strong> \n<ul class=\"fig-list\"><li>Funktionale Kernkomponente des Key Storage Providers (KSP, üblicherweise innerhalb des Crypto-Daemons oder eines geschützten Systemdienstes). \n</li><li>Verwaltet logische und physische Key-Slots und setzt Zugriffsentscheidungen durch (PEP).\n</li></ul>\n</li><li><strong>IAM unit of Key Storage Provider:</strong> \n<ul class=\"fig-list\"><li>IAM-Bewertungseinheit (PDP, Bindung an <code>ara::iam</code>), die Zugriffspolicies (Key Access Rulesets aus dem Deployment-Manifest) verwaltet und evaluiert.\n</li></ul>\n</li><li><strong>Schnittstellen &amp; Kanäle:</strong>\n<ul class=\"fig-list\"><li>Kommunikationskanal AA ↔ KSP: IPC-Grenze zur Übermittlung von Slot-Anfragen und Handle-Rückgaben.\n</li><li>Interner Schnittstellenpfad KSP ↔ IAM: Synchroner Kontrollfluss zur Autorisierungsprüfung basierend auf Prozessattributen und Slot-Identifikatoren.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Access Request (AA → KSP):</strong> \n<ul class=\"fig-list\"><li>Die Applikation fordert Zugriff auf einen definierten Key Slot an (Aufruf von <code>KeyStorageProvider::OpenKeySlot()</code> o. ä.).\n</li></ul>\n</li><li><strong>Policy Evaluation Query (KSP → IAM):</strong> \n<ul class=\"fig-list\"><li>Die funktionale KSP-Einheit ermittelt die verifizierte Prozessidentität der AA (z. B. UID/PID bzw. Security Token via OS-IPC) und übermittelt <code>Key Slot ID</code> + Identitätsmerkmale an die IAM-Einheit.\n</li></ul>\n</li><li><strong>Access Control Decision (IAM → KSP):</strong> \n<ul class=\"fig-list\"><li>Die IAM-Einheit gleicht die Identität und Capabilities der AA gegen die hinterlegten Zugriffsregeln (<em>Policies / Ruleset</em>) für den angeforderten Key Slot ab (z. B. Read, Write, Erase).\n</li><li>Rückgabe des Autorisierungsentscheids (<code>Grant</code> / <code>Deny</code>) an den KSP.\n</li></ul>\n</li><li><strong>Handle Provisioning (KSP → AA):</strong> \n<ul class=\"fig-list\"><li><strong>Access granted:</strong> KSP instanziiert bzw. kapselt die Ressource und liefert ein valides Container-Handle (<code>KeySlot::Uptr</code>) an die AA zurück.\n</li><li><strong>Access denied:</strong> KSP verwirft die Anfrage und gibt ein Null-Handle bzw. einen entsprechenden Fehlercode zurück.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Fehlerbehandlung im Applikationscode:</strong> Aufrufe zur Slot-Öffnung liefern <code>ara::core::Result&lt;KeySlot::Uptr&gt;</code>. Applikationsentwickler müssen Zugriffsverweigerungen explizit über <code>ara::crypto::SecurityErrc::kAccessViolation</code> bzw. <code>kPermissionDenied</code> abfangen; ein ungeprüftes Dereferenzieren führt zum Absturz (<code>nullptr</code>).\n</li><li><strong>Manifest-Konfiguration:</strong> Zugriffsrechte sind statisch über AUTOSAR-Modellierungsmanifeste festzulegen:\n<ul class=\"fig-list\"><li><em>Crypto Service Certificate/Key Slot Deployment</em>: Definition der Ziel-Slots und deren Zugriffsmodi.\n</li><li><em>IAM Access Rule Profile / Execution Manifest</em>: Explizite Zuweisung der IAM-Capabilities an die Executable der AA. Fehlt die Manifest-Zuordnung, blockiert IAM den Zugriff per Default (<em>Deny by Default</em>).\n</li></ul>\n</li><li><strong>Stack- &amp; Plattform-Implementierung:</strong> Die Integrität der AA-Identität darf nicht auf Parametern der Applikationsebene basieren. Die funktionale KSP-Einheit muss die Identitätsinformationen zwingend über vertrauenswürdige OS-/IPC-Mechanismen (z. B. Peer-Credentials über UNIX Domain Sockets) auflösen, um Privilegienerweiterungen zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-684ac4cd5d6a2edb", "to": "FIG-db4a5826b5bee4f8", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
